import {
  createAsync,
  useSubmission,
  useSearchParams,
  type RouteDefinition,
} from "@solidjs/router";
import { For, Show, Suspense, createSignal, createEffect } from "solid-js";
import { Portal } from "solid-js/web";
import { getAdminIzin, approveIzin, getPageNumbers } from "~/lib";
import { showToast } from "~/lib/toast";

export const route = {
  preload() {
    getAdminIzin({ page: 1, limit: 10, search: "", type: "", status: "" });
  },
} satisfies RouteDefinition;

// Backward compat: data lama pakai /uploads/, data baru /api/uploads?file=
const normalizeAttachmentUrl = (url: string) =>
  url.startsWith("/uploads/")
    ? `/api/uploads?file=${url.replace("/uploads/", "")}`
    : url;

const statusText = (status: string) => {
  const map: Record<string, string> = {
    PENDING: "Menunggu",
    APPROVED: "Disetujui",
    REJECTED: "Ditolak",
  };
  return map[status] || status;
};

export default function AdminIzin() {
  const approving = useSubmission(approveIzin);
  const [viewingAttachment, setViewingAttachment] = createSignal<string | null>(
    null,
  );
  const [searchParams, setSearchParams] = useSearchParams();

  createEffect(() => {
    if (searchParams.success === "update") {
      showToast("Status pengajuan izin berhasil diperbarui!", "success");
      setSearchParams({ success: null });
    }
  });

  createEffect(() => {
    if (approving.result && (approving.result as any) instanceof Error) {
      showToast((approving.result as any as Error).message, "error");
    }
  });

  // Filter signals
  const [searchQuery, setSearchQuery] = createSignal("");
  const [debouncedSearch, setDebouncedSearch] = createSignal("");
  const [filterType, setFilterType] = createSignal("");
  const [filterStatus, setFilterStatus] = createSignal("");

  // Pagination setup
  const [currentPage, setCurrentPage] = createSignal(1);
  const itemsPerPage = 10;

  let debounceTimer: any;
  const handleSearchInput = (val: string) => {
    setSearchQuery(val);
    clearTimeout(debounceTimer);
    debounceTimer = setTimeout(() => {
      setDebouncedSearch(val);
      setCurrentPage(1);
    }, 400);
  };

  const recordsData = createAsync(() =>
    getAdminIzin({
      page: currentPage(),
      limit: itemsPerPage,
      search: debouncedSearch(),
      type: filterType(),
      status: filterStatus(),
    }),
  );

  const totalPages = () => {
    const total = recordsData()?.total ?? 0;
    return Math.max(1, Math.ceil(total / itemsPerPage));
  };

  const paginatedRecords = () => {
    return recordsData()?.items ?? [];
  };

  return (
    <main>
      <h1 class="page-title">Kelola Pengajuan Izin</h1>

      <div class="filter-card" style="margin-bottom: var(--space-4);">
        <div class="form-group">
          <label>Cari Nama</label>
          <input
            type="text"
            placeholder="Cari nama atau username..."
            value={searchQuery()}
            onInput={(e) => handleSearchInput(e.currentTarget.value)}
          />
        </div>
        <div class="form-group">
          <label>Tipe Izin</label>
          <select
            value={filterType()}
            onChange={(e) => {
              setFilterType(e.currentTarget.value);
              setCurrentPage(1);
            }}
          >
            <option value="">Semua Tipe</option>
            <option value="SAKIT">Sakit</option>
            <option value="IZIN">Izin</option>
            <option value="CUTI">Cuti</option>
          </select>
        </div>
        <div class="form-group">
          <label>Status</label>
          <select
            value={filterStatus()}
            onChange={(e) => {
              setFilterStatus(e.currentTarget.value);
              setCurrentPage(1);
            }}
          >
            <option value="">Semua Status</option>
            <option value="PENDING">Pending</option>
            <option value="APPROVED">Setuju</option>
            <option value="REJECTED">Tolak</option>
          </select>
        </div>
        <button
          onClick={() => {
            setSearchQuery("");
            setDebouncedSearch("");
            setFilterType("");
            setFilterStatus("");
            setCurrentPage(1);
          }}
          class="btn-ghost"
          style="width: auto;"
        >
          Reset Filter
        </button>
      </div>

      <Suspense
        fallback={
          <div style="overflow-x: auto; opacity: 0.6; pointer-events: none;">
            <table class="data-table">
              <thead>
                <tr>
                  <th>No</th>
                  <th>Nama</th>
                  <th>Tipe</th>
                  <th>Tanggal Mulai</th>
                  <th>Tanggal Selesai</th>
                  <th>Alasan</th>
                  <th>Lampiran</th>
                  <th>Status</th>
                  <th>Aksi</th>
                </tr>
              </thead>
              <tbody>
                <For each={[1, 2, 3, 4, 5]}>
                  {() => (
                    <tr>
                      <td>
                        <div
                          class="skeleton"
                          style="width: 24px; height: 16px;"
                        ></div>
                      </td>
                      <td>
                        <div
                          class="skeleton"
                          style="width: 100px; height: 16px;"
                        ></div>
                      </td>
                      <td>
                        <div
                          class="skeleton"
                          style="width: 50px; height: 20px; border-radius: 4px;"
                        ></div>
                      </td>
                      <td>
                        <div
                          class="skeleton"
                          style="width: 80px; height: 16px;"
                        ></div>
                      </td>
                      <td>
                        <div
                          class="skeleton"
                          style="width: 80px; height: 16px;"
                        ></div>
                      </td>
                      <td>
                        <div
                          class="skeleton"
                          style="width: 150px; height: 16px;"
                        ></div>
                      </td>
                      <td>
                        <div
                          class="skeleton"
                          style="width: 70px; height: 24px; border-radius: 4px;"
                        ></div>
                      </td>
                      <td>
                        <div
                          class="skeleton"
                          style="width: 60px; height: 20px; border-radius: 4px;"
                        ></div>
                      </td>
                      <td>
                        <div
                          class="skeleton"
                          style="width: 100px; height: 24px;"
                        ></div>
                      </td>
                    </tr>
                  )}
                </For>
              </tbody>
            </table>
          </div>
        }
      >
        <div style="overflow-x: auto;">
          <table class="data-table">
            <thead>
              <tr>
                <th>No</th>
                <th>Nama</th>
                <th>Tipe</th>
                <th>Tanggal Mulai</th>
                <th>Tanggal Selesai</th>
                <th>Alasan</th>
                <th>Lampiran</th>
                <th>Status</th>
                <th>Aksi</th>
              </tr>
            </thead>
            <tbody>
              <Show
                when={paginatedRecords().length > 0}
                fallback={
                  <tr>
                    <td
                      colspan="9"
                      style="text-align: center; color: var(--color-text-secondary); padding: var(--space-5);"
                    >
                      Belum ada pengajuan izin.
                    </td>
                  </tr>
                }
              >
                <For each={paginatedRecords()}>
                  {(row, idx) => {
                    const startDate = new Date(
                      row.startDate,
                    ).toLocaleDateString("id-ID");
                    const endDate = new Date(row.endDate).toLocaleDateString(
                      "id-ID",
                    );

                    return (
                      <tr>
                        <td style="font-family: var(--font-mono); font-size: 13px;">
                          {(currentPage() - 1) * itemsPerPage + idx() + 1}
                        </td>
                        <td>
                          <strong>{row.user.fullName}</strong>
                          <div style="font-size: 12px; color: var(--color-text-secondary);">
                            @{row.user.username}
                          </div>
                          <Show when={row.user.phone}>
                            <div style="font-size: 11px; color: var(--color-text-secondary); margin-top: 2px; display: flex; align-items: center; gap: 4px;">
                              <svg
                                width="12"
                                height="12"
                                viewBox="0 0 24 24"
                                fill="none"
                                stroke="currentColor"
                                stroke-width="2"
                                stroke-linecap="round"
                                stroke-linejoin="round"
                                style="flex-shrink: 0; stroke: currentColor;"
                              >
                                <path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92z" />
                              </svg>
                              <span>{row.user.phone}</span>
                            </div>
                          </Show>
                        </td>
                        <td>
                          <span class="badge badge-izin">{row.type}</span>
                        </td>
                        <td>{startDate}</td>
                        <td>{endDate}</td>
                        <td title={row.reason}>
                          <div style="max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">
                            {row.reason}
                          </div>
                        </td>
                        <td>
                          <Show
                            when={row.attachment}
                            fallback={
                              <span style="color: var(--color-text-secondary); font-size: 13px;">
                                —
                              </span>
                            }
                          >
                            <button
                              type="button"
                              class="btn-secondary"
                              style="width: auto; height: 32px; padding: 0 12px; font-size: 12px; display: inline-flex;"
                              onClick={() =>
                                setViewingAttachment(
                                  normalizeAttachmentUrl(row.attachment!),
                                )
                              }
                            >
                              Lihat Surat
                            </button>
                          </Show>
                        </td>
                        <td>
                          <span
                            class={`badge badge-${row.status.toLowerCase()}`}
                          >
                            {statusText(row.status)}
                          </span>
                        </td>
                        <td>
                          <Show when={row.status === "PENDING"}>
                            <div style="display: flex; gap: var(--space-2);">
                              <form action={approveIzin} method="post">
                                <input type="hidden" name="id" value={row.id} />
                                <input
                                  type="hidden"
                                  name="status"
                                  value="APPROVED"
                                />
                                <button
                                  type="submit"
                                  class="btn-secondary"
                                  style="width: auto; height: 32px; padding: 0 12px; font-size: 12px;"
                                  disabled={approving.pending}
                                >
                                  Setujui
                                </button>
                              </form>
                              <form action={approveIzin} method="post">
                                <input type="hidden" name="id" value={row.id} />
                                <input
                                  type="hidden"
                                  name="status"
                                  value="REJECTED"
                                />
                                <button
                                  type="submit"
                                  class="btn-danger"
                                  style="width: auto; height: 32px; padding: 0 12px; font-size: 12px;"
                                  disabled={approving.pending}
                                >
                                  Tolak
                                </button>
                              </form>
                            </div>
                          </Show>
                          <Show when={row.status !== "PENDING"}>
                            <span style="color: var(--color-text-secondary); font-size: 13px;">
                              —
                            </span>
                          </Show>
                        </td>
                      </tr>
                    );
                  }}
                </For>
              </Show>
            </tbody>
          </table>
        </div>

        {/* Pagination Controls */}
        <Show when={(recordsData()?.total ?? 0) > 0}>
          <div class="pagination-container">
            <div class="pagination-info">
              Menampilkan {paginatedRecords().length} dari{" "}
              {recordsData()?.total ?? 0} pengajuan izin
            </div>
            <div class="pagination-buttons">
              <button
                class="btn-pagination"
                disabled={currentPage() === 1}
                onClick={() => setCurrentPage(currentPage() - 1)}
              >
                Sebelumnya
              </button>
              <For each={getPageNumbers(currentPage(), totalPages())}>
                {(page) => (
                  <Show
                    when={page !== "..."}
                    fallback={
                      <span style="padding: 0 8px; color: var(--color-text-secondary); align-self: center; font-weight: 600;">
                        ...
                      </span>
                    }
                  >
                    <button
                      class="btn-pagination"
                      classList={{ active: currentPage() === page }}
                      onClick={() => setCurrentPage(page as number)}
                    >
                      {page}
                    </button>
                  </Show>
                )}
              </For>
              <button
                class="btn-pagination"
                disabled={currentPage() === totalPages()}
                onClick={() => setCurrentPage(currentPage() + 1)}
              >
                Berikutnya
              </button>
            </div>
          </div>
        </Show>
      </Suspense>

      <Show when={viewingAttachment()}>
        {(url) => (
          <Portal>
            <div
              class="modal-overlay"
              onClick={() => setViewingAttachment(null)}
            >
              <div
                class="modal modal-animate"
                onClick={(e) => e.stopPropagation()}
                style="max-width: 600px; text-align: center;"
              >
                <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: var(--space-4); border-bottom: 1px solid var(--color-border); padding-bottom: var(--space-2);">
                  <h3 style="margin: 0; font-family: var(--font-headline); font-weight: 700;">
                    Surat Keterangan Sakit
                  </h3>
                  <button
                    class="theme-toggle"
                    style="font-size: 24px; padding: 0; cursor: pointer;"
                    onClick={() => setViewingAttachment(null)}
                  >
                    ×
                  </button>
                </div>
                <Show
                  when={viewingAttachment()?.toLowerCase().endsWith(".pdf")}
                  fallback={
                    <img
                      src={url()}
                      alt="Surat Sakit"
                      style="max-width: 100%; max-height: 70vh; object-fit: contain; border-radius: var(--radius-md); box-shadow: var(--shadow-md);"
                    />
                  }
                >
                  <embed
                    src={url()}
                    type="application/pdf"
                    width="100%"
                    height="500px"
                    style="border-radius: var(--radius-md); border: 1px solid var(--color-border);"
                  />
                </Show>
                <div style="margin-top: var(--space-4); display: flex; justify-content: center;">
                  <button
                    class="btn-ghost"
                    type="button"
                    onClick={() => setViewingAttachment(null)}
                    style="width: auto; padding: 0 var(--space-4);"
                  >
                    Tutup
                  </button>
                </div>
              </div>
            </div>
          </Portal>
        )}
      </Show>
    </main>
  );
}
